package com.example.shop.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.NamedQuery;
import jakarta.persistence.Table;
import jakarta.persistence.UniqueConstraint;
import java.lang.Long;
import java.lang.String;

@Entity
@Table(name = "widget", indexes = {@Index(name = "ix_widget_label", columnList = "label"), @Index(columnList = "id, label", unique = true)}, uniqueConstraints = {@UniqueConstraint(columnNames = {"label", "code"})})
@NamedQuery(name = "Widget.byLabel", query = "select w from Widget w where w.label = :label")
@NamedQuery(name = "Widget.dynamic", query = "select w from Widget w " + "order by w.id")
public class Widget {

    @Id
    private Long id;

    @Column(name = "label")
    private String label;

    private String code;
}
